402	      const requestId = requireId("provider.connect");
403	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.method !== "string" || !msg.method) {
404	        throw new ProtocolError("provider.connect requires provider and method", requestId);
405	      }
406	      if (msg.key !== undefined && typeof msg.key !== "string") throw new ProtocolError("provider.connect key must be a string", requestId);
407	      if (msg.endpoint !== undefined && (typeof msg.endpoint !== "string" || !msg.endpoint || msg.endpoint.length > 2048 || /[\r\n\0]/.test(msg.endpoint))) {
408	        throw new ProtocolError("provider.connect endpoint must be a valid single-line URL", requestId);
409	      }
410	      return {
411	        type: "provider.connect", id: requestId, provider: msg.provider, method: msg.method,
412	        ...(typeof msg.key === "string" ? { key: msg.key } : {}),
413	        ...(typeof msg.endpoint === "string" ? { endpoint: msg.endpoint } : {}),
414	      };
415	    }
416	    case "provider.cancel":
417	      return { type: "provider.cancel", id: requireId("provider.cancel") };
418	    case "provider.local-cancel":
419	      return { type: "provider.local-cancel", id: requireId("provider.local-cancel") };
420	    case "provider.disconnect": {
421	      const requestId = requireId("provider.disconnect");
422	      if (typeof msg.provider !== "string" || !msg.provider) throw new ProtocolError("provider.disconnect requires provider", requestId);
423	      return { type: "provider.disconnect", id: requestId, provider: msg.provider };
424	    }
425	    case "shutdown":
426	      return { type: "shutdown" };
427	    default:
428	      throw new ProtocolError(`unknown message type: ${String(msg.type)}`, id);
429	  }
430	}
431	
432	export function capText(text: string, max: number = MAX_TEXT_FIELD): string {
433	  if (text.length <= max) return text;
434	  return `${text.slice(0, max)}…[truncated ${text.length - max} chars]`;
435	}
436	
437	/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
438	const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;
439	
440	export function stripEscapes(text: string): string {
441	  return text.replace(TERMINAL_ESCAPE, "");
442	}
443	
444	/** Secrets redacted from text with terminal escape sequences removed: the shared first step of every operator-facing one-line projection. */
445	export function redactPlain(text: string): string {
446	  return redactSecrets(stripEscapes(text));
447	}
448	
449	/** Operator-supplied text as shown to an operator or written to a record: escapes and control characters gone, secrets redacted, one line, capped. */
450	export function safeOperatorText(text: string, max = 300): string {
451	  return redactSecrets(stripEscapes(String(text)).replace(/[\x00-\x1f\x7f-\x9f]+/g, " ")).replace(/\s+/g, " ").trim().slice(0, max);
452	}
453	
454	export function toolSubject(args: Record<string, any>, tool?: string): string {
455	  if (tool === "steering_conflict" && Array.isArray(args.negates)) {
456	    const ids = args.negates.map((n: any) => safeOperatorText(String(n?.id ?? ""), 12)).join(", ");
457	    return safeOperatorText(`steering ${args.steering} negates ${ids}: ${args.text}`, 200);
458	  }
459	  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
460	  return redactPlain(String(subject)).replace(/\s+/g, " ").trim().slice(0, 200);
461	}
462	
463	/** Copy of a turn with secrets redacted from its free-text fields; enums, counts, ids and hashes are left as-is. */
464	export function projectTurn(turn: TurnResult): TurnResult {
465	  const redactOptional = (text: string | undefined) => (text === undefined ? undefined : redactSecrets(text));
466	  return {
467	    ...turn,
468	    detail: redactOptional(turn.detail),
469	    verification: turn.verification ? { ...turn.verification, command: redactOptional(turn.verification.command) } : null,
470	    interruption: turn.interruption ? { ...turn.interruption, outstandingTool: redactOptional(turn.interruption.outstandingTool) } : null,
471	    inferenceFailure: turn.inferenceFailure ? { ...turn.inferenceFailure, message: redactSecrets(turn.inferenceFailure.message) } : null,
472	    ...(turn.convergence
473	      ? {
474	          convergence: {
475	            ...turn.convergence,
476	            evidence: redactSecrets(turn.convergence.evidence),
477	            attempts: turn.convergence.attempts.map((a) => ({
478	              ...a,
479	              command: redactSecrets(a.command),
480	              ...(a.failedCheck ? { failedCheck: redactSecrets(a.failedCheck) } : {}),
481	              ...(a.failingTests ? { failingTests: a.failingTests.map((t) => redactSecrets(t)) } : {}),
482	            })),
483	          },
484	        }
485	      : {}),
486	    ...(turn.turnEvidence
487	      ? { turnEvidence: { ...turn.turnEvidence, verifierRuns: turn.turnEvidence.verifierRuns.map((r) => ({ ...r, command: redactSecrets(r.command) })) } }
488	      : {}),
489	    ...(turn.providerRecovery
490	      ? {
491	          providerRecovery: turn.providerRecovery.map((r) => ({
492	            ...r,
493	            reason: redactOptional(r.reason),
494	            submissions: r.submissions.map((s) => ({ ...s, message: redactSecrets(s.message) })),
495	          })),
496	        }
497	      : {}),
498	  };
499	}
500	
501	/** The notice key of every provider-wait line: one live row that each transition replaces. */
502	export const PROVIDER_STATUS_KEY = "provider.recovery";
503	export const STARTUP_PROVIDER_KEY = "provider.startup";
504	
505	export interface StatusNotice {
506	  text: string;
507	  key: string;
508	  /** The raw cause (redacted); never part of `text`. */
509	  detail?: string;
510	}
511	
512	/** What went wrong, in words an operator can act on. */
513	function providerProblemWords(record: ProviderRecoveryRecord): string {
514	  const last = record.submissions[record.submissions.length - 1];
515	  const status = last?.httpStatus;
516	  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
517	  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
518	  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
519	  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
520	  if (record.condition === "DRAINING") return "the provider is restarting";
521	  if (last?.kind === "timeout") return "the provider did not answer in time";
522	  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
523	  return "the provider returned an error";
524	}
525	
526	function minutesWords(ms: number): string {
527	  const minutes = Math.round(ms / 60_000);
528	  return minutes < 1 ? "under a minute" : `about ${minutes} min`;
529	}
530	
531	function rawProviderCause(record: ProviderRecoveryRecord): string {
532	  const last = record.submissions[record.submissions.length - 1];
533	  const parts = [
534	    `condition ${record.condition}${last?.httpStatus ? `, HTTP ${last.httpStatus}` : ""}${last ? `, ${last.kind}, execution ${last.execution}` : ""}`,
535	    last?.message,
536	    record.reason ? `recovery: ${record.reason}` : undefined,
537	    last?.requestId ? `request ${last.requestId}` : undefined,
538	  ];
539	  return redactSecrets(scrubUrls(parts.filter(Boolean).join("\n")));
540	}
541	
542	/**
543	 * The provider-wait status line for one recovery transition (PROBING produces none). Every transition carries the
544	 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
545	 */
546	export function providerRecoveryStatus(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): StatusNotice | undefined {
547	  if (record.state === "PROBING") return undefined;
548	  const detail = rawProviderCause(record);
549	  const where = record.endpoint ? ` at ${persistableEndpoint(record.endpoint)}` : "";
550	  const problem = providerProblemWords(record);
551	  switch (record.state) {
552	    case "WAITING": {
553	      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
554	      const left = minutesWords(Math.max(0, record.policy.deadlineMs - record.waitedMs));
555	      const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
556	      const text = `Waiting for the model provider${where}: ${problem}. Retry ${record.submissions.length}, next attempt in ${secs}s; gives up in ${left}. Your work is kept. /details shows the raw error; esc cancels.${discarded}`;
557	      return { text: redactSecrets(text), key: PROVIDER_STATUS_KEY, detail };
558	    }
559	    case "RESUMED":
560	      return { text: `The model provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`, key: PROVIDER_STATUS_KEY, detail: `Recovered; the earlier error was:\n${detail}` };
561	    case "CANCELLED":
562	      return { text: "Stopped waiting for the model provider.", key: PROVIDER_STATUS_KEY, detail };
563	    default:
564	      return {
565	        text: redactSecrets(`Nexus stopped retrying the model provider${where}: ${problem}. Check the connection or use /connect, then send your message again. /details shows the raw error.`),
566	        key: PROVIDER_STATUS_KEY,
567	        detail,
568	      };
569	  }
570	}
571	
572	/** The answer to a prompt sent while the provider is still down: short, because the start-up notice already gave the steps. */
573	export function noProviderRefusal(problem: { endpoint: string; endpoints?: string[]; nothingThere?: boolean }): string {
574	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
575	  const why = problem.nothingThere === false ? `could not connect to ${named}` : `nothing answers at ${named}`;
576	  return redactSecrets(`Not sent: no model is connected (${why}). Use /connect or start a local model server, then send it again.`);
577	}
578	
579	/** First run with nothing to talk to: what is missing, what to do next, where to read more. The raw cause goes in `detail`. */
580	export function noProviderNotice(problem: { kind: "unreachable" | "rejected"; endpoint: string; endpoints?: string[]; detail: string; blocking?: boolean; nothingThere?: boolean }): StatusNotice {
581	  if (problem.kind === "rejected" || problem.blocking === false) {
582	    // Only a warning: the start-up check can be refused where chat is not (a token not yet refreshed, a key limited to chat).
583	    // With several endpoints that failed, each is named and the wording does not say how each failed (the detail does).
584	    const many = (problem.endpoints?.length ?? 0) > 1;
585	    const verb = many ? "did not pass" : problem.kind === "rejected" ? "rejected the credentials on" : "did not answer";
586	    return {
587	      text: redactSecrets(
588	        `${many ? problem.endpoints!.join(", ") : problem.endpoint} ${verb} the start-up check. Nexus will still try your messages; ` +
589	          `if they fail, type /connect to sign in again or check the API key and the server. \`nexus doctor\` checks the setup.`,
590	      ),
591	      key: STARTUP_PROVIDER_KEY,
592	      detail: redactSecrets(problem.detail),
593	    };
594	  }
595	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
596	  const missing = problem.nothingThere === false ? `No model is connected: Nexus could not connect to ${named}.` : `No model is connected: nothing answers at ${named}.`;
597	  const text =
598	    `${missing} Next: type /connect to sign in or add an API key, or start a local model server (LM Studio, Ollama, llama.cpp) ` +
599	    `and send your message again. \`nexus doctor\` checks the setup; docs/CLOUD_PROVIDERS.md lists providers.`;
600	  return { text: redactSecrets(text), key: STARTUP_PROVIDER_KEY, detail: redactSecrets(problem.detail) };
601	}
602	
603	/** Lines of a command's output carried in `tool.end` for the transcript preview. */
604	export const TOOL_PREVIEW_LINES = 8;
605	
606	export interface ToolSummary {
607	  summary: string;
608	  lines: number;
609	  preview?: string;
610	  exit_code?: number | null;
611	  duration_ms?: number;
612	  timed_out?: boolean;
613	}
614	
615	/**
616	 * What the transcript shows for a finished tool. A command's JSON result (`stdout`, `stderr`, `exit_code`) becomes a
617	 * real summary (`exit 0 · 122 lines`, or `no output`), the count of its output lines and a bounded preview of them;
618	 * other tools keep the first line of their output (or error) as the summary.
619	 */
620	export function toolSummary(success: boolean, output: string, error?: string): ToolSummary {
621	  const command = commandResult(output);
622	  if (command) {
623	    const body = [command.stdout.trimEnd(), command.stderr.trimEnd()].filter(Boolean).join("\n");
624	    const rows = body ? body.split(/\r?\n/) : [];
625	    const exit = command.timed_out ? "timed out" : command.exit_code === null ? "no exit code" : `exit ${command.exit_code}`;
626	    const failure = success ? "" : (error ?? "").split(/\r?\n/).find((line) => line.trim())?.trim() ?? "";
627	    const summary = failure && !failure.startsWith("{") ? failure : `${exit} · ${rows.length ? `${rows.length} line${rows.length === 1 ? "" : "s"}` : "no output"}`;
628	    return {
629	      summary: redactPlain(summary).replace(/\s+/g, " ").slice(0, MAX_SUMMARY),
630	      lines: rows.length,
631	      preview: (rows.length > TOOL_PREVIEW_LINES ? rows.slice(-TOOL_PREVIEW_LINES) : rows).map((row) => safeTerminal(row).slice(0, 400)).join("\n"),
632	      exit_code: command.exit_code,
633	      ...(command.duration_ms !== undefined ? { duration_ms: command.duration_ms } : {}),
634	      ...(command.timed_out ? { timed_out: true } : {}),
635	    };
636	  }
637	  const text = redactPlain(success ? output || "" : error || output || "").trim();
638	  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
639	  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
640	}
641	
642	/** The structured result of a shell command tool, when `output` is one. */
643	function commandResult(output: string): { stdout: string; stderr: string; exit_code: number | null; duration_ms?: number; timed_out?: boolean } | undefined {
644	  if (!output || output.trimStart()[0] !== "{") return undefined;
645	  try {
646	    const parsed = JSON.parse(output);
647	    if (parsed && typeof parsed === "object" && typeof parsed.stdout === "string" && "exit_code" in parsed) {
648	      return {
649	        stdout: parsed.stdout,
650	        stderr: typeof parsed.stderr === "string" ? parsed.stderr : "",
651	        exit_code: typeof parsed.exit_code === "number" ? parsed.exit_code : null,
652	        ...(typeof parsed.duration_ms === "number" ? { duration_ms: parsed.duration_ms } : {}),
653	        ...(parsed.timed_out === true ? { timed_out: true } : {}),
654	      };
655	    }
656	  } catch {}
657	  return undefined;
658	}
