1	/**
2	 * Nexus sidecar protocol v1: newline-delimited JSON between the Ratatui client (parent) and the
3	 * Node agent sidecar (child). The sidecar projects agent state; it never asks the client to decide outcomes.
4	 */
5	import type { ProviderRecoveryRecord, TurnResult } from "./core/turn.js";
6	import { redactSecrets, safeTerminal } from "./ui.js";
7	import { persistableEndpoint, scrubUrls } from "./core/endpoint_identity.js";
8	import type { ApprovalReview } from "./approval_review.js";
9	import type { SlashSpec } from "./slash/catalog.js";
10	import type { EvidenceStatus, ReceiptSection } from "./evidence.js";
11	import type { Catalog } from "./model_catalog.js";
12	
13	export const PROTOCOL_VERSION = 1;
14	/**
15	 * The inclusive range of protocol versions this sidecar can speak: `hello` announces it, `initialize` negotiates
16	 * inside it, and `parseCommand` accepts a message whose `v` lies in it. A version bump changes this pair (and
17	 * `PROTOCOL_VERSION`, the version the sidecar speaks by default) and nothing else in the negotiation.
18	 */
19	export const PROTOCOL_MIN = 1;
20	export const PROTOCOL_MAX = PROTOCOL_VERSION;
21	/** Largest protocol version number `initialize` accepts in a client's range (a bound on the field, not a version that exists). */
22	export const MAX_PROTOCOL_NUMBER = 65_535;
23	/** Longest `client.name` and `client.version` that `initialize` accepts. */
24	export const MAX_CLIENT_FIELD = 100;
25	
26	/**
27	 * Stable features of this sidecar, announced in `hello` and `initialized`. Each name is the `type` of a command a
28	 * client may send beyond the minimal set every sidecar handles (`prompt.submit`, `cancel`, `approve`, `deny`,
29	 * `shutdown`), so a client checks `capabilities.includes(type)` before it sends that command. Sorted; a name is
30	 * never removed or given a new meaning within a protocol version.
31	 */
32	export const SIDECAR_CAPABILITIES = [
33	  /** `answer`: the operator's decision on a question a turn ended BLOCKED / NEEDS_INPUT with. */
34	  "answer",
35	  /** `checkpoint.choice`: the answer to a `checkpoint.choice.request` event. */
36	  "checkpoint.choice",
37	  /** `model.select`: switch model between turns; answered with `model.result`. */
38	  "model.select",
39	  /** `models.list`: providers and models; answered with `models.catalog`. */
40	  "models.list",
41	  /** `provider.connect`, with `provider.cancel` and `provider.local-cancel` for the same request; answered with `provider.auth` and `provider.result`. */
42	  "provider.connect",
43	  /** `provider.disconnect`: answered with `provider.result`. */
44	  "provider.disconnect",
45	  /** `receipt`: the evidence receipt of the last turn; answered with the `receipt` event. */
46	  "receipt",
47	  /** `slash`: run a command of the catalogue `hello` carries; answered with `slash.result`. */
48	  "slash",
49	  /** `steer`: guidance for the work in progress; answered with `steer.ack`. */
50	  "steer",
51	  /** `tool.detail`: the full record of one tool call; answered with the `tool.detail` event. */
52	  "tool.detail",
53	] as const;
54	
55	/**
56	 * Experimental features this sidecar offers (none today). A new method sits here, refused with
57	 * `EXPERIMENTAL_DISABLED` unless the client sent `initialize` with `experimental: true`, until a conformance suite
58	 * has run against two real clients (docs/v1.3.0/PLAN.md, principle 8); then its name moves to SIDECAR_CAPABILITIES.
59	 */
60	export const EXPERIMENTAL_FEATURES: readonly string[] = [];
61	export const MAX_TEXT_FIELD = 8000;
62	/**
63	 * Longest clipboard text `/paste` puts into the composer, and the limit of the `slash.result` composer field. It keeps
64	 * the escaped `slash.result` line under the TUI's 1 MiB protocol line cap.
65	 */
66	export const MAX_PASTE = 100_000;
67	export const MAX_SUMMARY = 160;
68	export const MAX_SLASH_OUTPUT = 32_000;
69	
70	/**
71	 * `UNSUPPORTED_PROTOCOL`: `initialize` named a version range that shares no version with the sidecar's.
72	 * `EXPERIMENTAL_DISABLED`: an experimental feature was used on a connection that did not enable it at `initialize`.
73	 */
74	export type ErrorCode = "BAD_REQUEST" | "BUSY" | "NO_PENDING_APPROVAL" | "NOT_FOUND" | "INTERNAL" | "NO_PROVIDER" | "UNSUPPORTED_PROTOCOL" | "EXPERIMENTAL_DISABLED";
