293	const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;
294	
295	/** Truncation can split a surrogate pair; a lone surrogate would serialize as JSON the client cannot decode. */
296	export function encodeEvent(event: SidecarEvent): string {
297	  const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.replace(LONE_SURROGATE, "\uFFFD") : value);
298	  return JSON.stringify({ v: PROTOCOL_VERSION, ...event }, wellFormed) + "\n";
299	}
