1	/**
2	 * What an operator needs to judge a gated tool call, built from the call's arguments. The client renders it
3	 * (unified diff, command line); the sidecar never decides whether the change is acceptable.
4	 */
5	import * as fs from "node:fs";
6	import * as path from "node:path";
7	import { redactSecrets } from "./ui.js";
8	import { describeDeletion } from "./delete_preview.js";
9	
10	export const MAX_REVIEW_TEXT = 100_000;
11	
12	export type ApprovalReview =
13	  | { kind: "change"; path: string; before: string | null; after: string; created: boolean; truncated: boolean }
14	  | { kind: "patch"; path: string; patch: string; truncated: boolean }
15	  | { kind: "command"; command: string }
16	  | { kind: "verifier"; command: string; script?: string; detail?: string }
17	  | { kind: "args"; text: string; truncated: boolean };
18	
19	function capped(text: string): { text: string; truncated: boolean } {
20	  const clean = redactSecrets(text);
21	  return clean.length > MAX_REVIEW_TEXT ? { text: clean.slice(0, MAX_REVIEW_TEXT), truncated: true } : { text: clean, truncated: false };
22	}
23	
24	/**
25	 * Whether `file` exists, and its text when it is a regular file whose real path stays inside `workspace` and is
26	 * small enough to show. Symlinks are resolved first, so a link cannot pull outside content into the review.
27	 */
28	function currentText(workspace: string, file: string): { exists: boolean; text: string | null } {
29	  let root: string;
30	  try {
31	    root = fs.realpathSync(workspace);
32	  } catch {
33	    return { exists: false, text: null };
34	  }
35	  const lexical = path.resolve(root, file);
36	  if (!fs.existsSync(lexical)) return { exists: false, text: null };
37	  try {
38	    const target = fs.realpathSync(lexical);
39	    if (target !== root && !target.startsWith(root + path.sep)) return { exists: true, text: null };
40	    const stat = fs.statSync(target);
41	    if (!stat.isFile() || stat.size > MAX_REVIEW_TEXT * 4) return { exists: true, text: null };
42	    return { exists: true, text: fs.readFileSync(target, "utf-8") };
43	  } catch {
44	    return { exists: true, text: null };
45	  }
46	}
47	
48	export function approvalReview(tool: string, args: Record<string, any>, workspace: string): ApprovalReview {
49	  const file = typeof args.path === "string" ? args.path : "";
50	  switch (tool) {
51	    case "edit_file": {
52	      const before = capped(String(args.old_content ?? ""));
53	      const after = capped(String(args.new_content ?? ""));
54	      return { kind: "change", path: file, before: before.text, after: after.text, created: false, truncated: before.truncated || after.truncated };
55	    }
56	    case "write_file": {
57	      const current = currentText(workspace, file);
58	      const before = current.text === null ? null : capped(current.text);
59	      const after = capped(String(args.content ?? ""));
60	      return {
61	        kind: "change",
62	        path: file,
63	        before: before ? before.text : null,
64	        after: after.text,
65	        created: !current.exists,
66	        truncated: after.truncated || Boolean(before?.truncated),
67	      };
68	    }
69	    case "patch_file": {
70	      const patch = capped(String(args.patch ?? ""));
71	      return { kind: "patch", path: file, patch: patch.text, truncated: patch.truncated };
72	    }
73	    // Text, so an older client shows it as it shows any arguments; built without reading outside the workspace.
74	    case "delete_file":
75	      return { kind: "args", text: redactSecrets(describeDeletion(workspace, args)), truncated: false };
76	    case "run_command":
77	      return { kind: "command", command: redactSecrets(String(args.command ?? "")) };
78	    case "verifier": {
79	      const command = redactSecrets(String(args.command ?? ""));
80	      const script = args.script !== undefined ? capped(String(args.script)).text : undefined;
81	      const detail = args.detail !== undefined ? redactSecrets(String(args.detail)) : undefined;
82	      return { kind: "verifier", command, script, detail };
83	    }
84	    default: {
85	      const text = capped(JSON.stringify(args, null, 2));
86	      return { kind: "args", text: text.text, truncated: text.truncated };
87	    }
88	  }
89	}
