1	/**
2	 * Evidence the live TUI opens after the fact: each tool call's full record, and the receipt for the last turn.
3	 * Everything here is a redacted projection; nothing decides an outcome.
4	 */
5	import type { ValidationReceipt } from "./core/candidate.js";
6	import type { TurnResult } from "./core/turn.js";
7	import { capText, redactPlain } from "./protocol.js";
8	import { redactSecrets, safeTerminal } from "./ui.js";
9	import { type ObjectiveLedger, requirementRows } from "./core/objective.js";
10	
11	export const MAX_DETAIL = 64_000;
12	/** Full diffs are kept larger than other detail: inspecting the complete change is their purpose. */
13	export const MAX_DIFF_DETAIL = 256_000;
14	export const MAX_EVIDENCE = 200;
15	
16	export type EvidenceSource = "tool" | "model";
17	export type EvidenceStatus = "running" | "succeeded" | "failed";
18	
19	export interface EvidenceRecord {
20	  evidence: string;
21	  turnId: string;
22	  tool: string;
23	  subject: string;
24	  /** Who produced this: a tool that ran (always, for ledger records) or the model's own assertion. Absent on older records. */
25	  source?: EvidenceSource;
26	  /** Arguments as pretty-printed JSON. */
27	  args: string;
28	  status: EvidenceStatus;
29	  output: string;
30	  startedAt: number;
31	  durationMs: number | null;
32	  /** Unified diff of the file change this call made (redacted, capped at MAX_DIFF_DETAIL). */
33	  diff?: string;
34	  /** Characters in the complete (redacted) diff, before the cap. */
35	  diffChars?: number;
36	  /** Where the complete diff was written, when it was. */
37	  diffPath?: string;
38	}
39	
40	/**
41	 * Pretty JSON with each string value redacted before encoding: quoting turns `KEY="value"` into `KEY=\"value\"`
42	 * and escapes into literal `\u001b`, both of which a pass over the encoded text misses.
43	 */
44	export function redactedJson(value: unknown): string {
45	  const json = JSON.stringify(value ?? {}, (_key, v) => (typeof v === "string" ? redactPlain(v) : v), 2);
46	  return redactSecrets(json);
47	}
48	
49	/** Tool output is usually JSON text; its string values are redacted before re-encoding, as with arguments. */
50	function redactedOutput(text: string): string {
51	  try {
52	    const parsed: unknown = JSON.parse(text);
53	    if (typeof parsed === "string" || (parsed !== null && typeof parsed === "object")) return redactedJson(parsed);
54	  } catch {
55	    // Plain text output.
56	  }
57	  return text;
58	}
59	
60	/** A diff as it may be shown or stored: secrets redacted, then control characters made visible. */
61	export function safeDiffText(diff: string): string {
62	  return safeTerminal(diff);
63	}
64	
65	function clean(text: string): string {
66	  return capText(redactPlain(text), MAX_DETAIL);
67	}
68	
69	/** The latest tool calls of this session; the oldest is dropped first. */
70	export class EvidenceLedger {
71	  private readonly records = new Map<string, EvidenceRecord>();
72	  private seq = 0;
73	
74	  constructor(
75	    private readonly limit: number = MAX_EVIDENCE,
76	    private readonly now: () => number = Date.now,
77	  ) {}
78	
79	  start(turnId: string, tool: string, subject: string, args: Record<string, unknown>): string {
80	    const evidence = `e${++this.seq}`;
81	    this.records.set(evidence, {
82	      evidence,
83	      turnId,
84	      tool,
85	      subject,
86	      source: "tool",
87	      args: clean(redactedJson(args)),
88	      status: "running",
89	      output: "",
90	      startedAt: this.now(),
91	      durationMs: null,
92	    });
93	    for (const oldest of this.records.keys()) {
94	      if (this.records.size <= this.limit) break;
95	      this.records.delete(oldest);
96	    }
97	    return evidence;
98	  }
99	
100	  end(evidence: string, success: boolean, output: string, error?: string, denied = false): void {
101	    const record = this.records.get(evidence);
102	    if (!record) return;
103	    if (denied) {
104	      // The call never ran: what the operator sees is their own decision, and the wait for it is not a run time.
105	      record.status = "failed";
106	      record.output = DENIED_BY_OPERATOR;
107	      record.durationMs = null;
108	      return;
109	    }
110	    const parts = success || !error || error === output ? [output] : [output, error];
111	    record.status = success ? "succeeded" : "failed";
112	    record.output = clean(parts.filter(Boolean).map(redactedOutput).join("\n"));
113	    record.durationMs = Math.max(0, this.now() - record.startedAt);
114	  }
115	
116	  /**
117	   * Attaches the diff of the change the call made; several files (rare) are appended in order. Control characters are
118	   * made visible rather than removed, so the diff still says what the file holds.
119	   */
120	  attachDiff(evidence: string, diff: string, diffPath?: string): void {
121	    const record = this.records.get(evidence);
122	    if (!record || !diff) return;
123	    const full = safeDiffText(diff);
124	    const joined = record.diff ? `${record.diff}\n${full}` : full;
125	    record.diffChars = (record.diffChars ?? 0) + full.length + (record.diff ? 1 : 0);
126	    record.diff = capText(joined, MAX_DIFF_DETAIL);
127	    if (diffPath) record.diffPath = diffPath;
128	  }
129	
130	  get(evidence: string): EvidenceRecord | undefined {
131	    return this.records.get(evidence);
132	  }
133	}
