// What the generators of the two command-result schemas share (gen_run_result_schema.mjs for `nexus run --json`,
// gen_verify_result_schema.mjs for `nexus verify --json`): one root type and one version constant in one contract
// source, written with the `SchemaBuilder` of gen_protocol_schema.mjs, and a ledger keyed by `schema_version`.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { API, SymbolFlags } from "typescript/unstable/sync";
import { SchemaBuilder, sha256, sortKeys } from "./gen_protocol_schema.mjs";

export const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const repo = path.resolve(cli, "..");

/**
 * The schema text for `rootType` as `source` (relative to cli/) declares it now, and the value of `versionConst`.
 * `script` names the generator in errors; `title(version)` and `description` are the schema's annotations.
 */
export function generateResultSchema({ script, source, rootType, versionConst, title, description }) {
  const api = new API({ cwd: cli });
  try {
    const snapshot = api.updateSnapshot({ openProjects: [path.join(cli, "tsconfig.json")] });
    const project = snapshot.getProjects()[0];
    if (!project) throw new Error(`${script}: cli/tsconfig.json did not load as a project`);
    const checker = project.checker;
    const sourceAt = { document: path.join(cli, source), position: 0 };
    const versionSymbol = checker.resolveName(versionConst, SymbolFlags.Value, sourceAt);
    const version = versionSymbol && checker.getTypeOfSymbol(versionSymbol)?.value;
    if (!Number.isInteger(version)) throw new Error(`${script}: ${versionConst} is not an integer literal in ${source}`);
    const rootSymbol = checker.resolveName(rootType, SymbolFlags.TypeAlias, sourceAt);
    if (!rootSymbol) throw new Error(`${script}: ${rootType} is not declared in ${source}`);
    const root = checker.getDeclaredTypeOfSymbol(rootSymbol);
    if (root.isErrorType()) throw new Error(`${script}: ${rootType} did not resolve`);

    const builder = new SchemaBuilder(checker);
    const rootSchema = builder.schemaOf(root, rootType);
    const schema = {
      $schema: "https://json-schema.org/draft/2020-12/schema",
      title: title(version),
      description,
      ...rootSchema,
      $defs: sortKeys(builder.defs),
    };
    return { version, text: `${JSON.stringify(schema, null, 2)}\n` };
  } finally {
    api.close();
  }
}

/**
 * The version-decision rule (the same as the protocol ledger's, with the key `schema_version`): the newest ledger entry
 * must name the current schema version and the hash of the checked-in schema. Returns what is wrong, or undefined.
 */
export function resultLedgerProblem(schemaText, ledger, version, versionConst) {
  if (!Array.isArray(ledger) || ledger.length === 0) return "the ledger has no entries";
  const last = ledger[ledger.length - 1];
  if (last.schema_version !== version) return `the newest ledger entry is for schema_version ${last.schema_version}, but ${versionConst} is ${version}`;
  const hash = sha256(schemaText);
  if (last.schemaSha256 !== hash) return `the newest ledger entry records schema ${last.schemaSha256}, but the schema is ${hash}: add an entry that records the version decision`;
  return undefined;
}

/** The command line of a generator: write the schema, or with `--check` exit 1 when the schema or its ledger is stale. */
export function resultSchemaMain({ script, generate, schemaFile, ledgerFile, ledgerProblem }) {
  const { version, text } = generate();
  const file = schemaFile(version);
  const shown = path.relative(repo, file).split(path.sep).join("/");
  const ledgerShown = path.relative(repo, ledgerFile).split(path.sep).join("/");
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : undefined;
    if (current !== text) {
      console.error(`${shown} is ${current === undefined ? "missing" : "out of date"}: run \`node cli/scripts/${script}.mjs\`, then record the version decision in ${ledgerShown}`);
      process.exit(1);
    }
    const problem = ledgerProblem(current, fs.existsSync(ledgerFile) ? JSON.parse(fs.readFileSync(ledgerFile, "utf8")) : [], version);
    if (problem) {
      console.error(`${ledgerShown}: ${problem}`);
      process.exit(1);
    }
    console.log(`${shown} is current`);
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
    console.log(`wrote ${shown} (sha256 ${sha256(text)})`);
  }
}
// Generates the two JSON Schemas (draft 2020-12) of the audit bundle (GV-2) from the types in src/audit_contract.ts,
// with the `SchemaBuilder` of gen_protocol_schema.mjs (see docs/protocol/README.md): deterministic output, compared
// byte for byte.
//   audit-bundle-v<N>.schema.json          `AuditBundleDocument`: manifest.json, or the signature envelope manifest.sig.json
//   audit-verify-result-v<N>.schema.json   `AuditVerifyOutput`: the document a verification prints
//
//   node scripts/gen_audit_schema.mjs           write both schemas under docs/protocol/
//   node scripts/gen_audit_schema.mjs --check   exit 1 when a checked-in schema or its version ledger is stale
import path from "node:path";
import { fileURLToPath } from "node:url";
import { generateResultSchema, repo, resultLedgerProblem, resultSchemaMain } from "./result_schema.mjs";

const SCRIPT = "gen_audit_schema";
const SOURCE = "src/audit_contract.ts";

export const AUDIT_BUNDLE_LEDGER_FILE = path.join(repo, "docs", "protocol", "AUDIT_BUNDLE_VERSIONS.json");
export const auditBundleSchemaFile = (version) => path.join(repo, "docs", "protocol", `audit-bundle-v${version}.schema.json`);
export const AUDIT_VERIFY_RESULT_LEDGER_FILE = path.join(repo, "docs", "protocol", "AUDIT_VERIFY_RESULT_VERSIONS.json");
export const auditVerifyResultSchemaFile = (version) => path.join(repo, "docs", "protocol", `audit-verify-result-v${version}.schema.json`);

/** The schema text for `AuditBundleDocument` as src/audit_contract.ts declares it now, and its `AUDIT_BUNDLE_SCHEMA_VERSION`. */
export function generateAuditBundleSchema() {
  return generateResultSchema({
    script: SCRIPT,
    source: SOURCE,
    rootType: "AuditBundleDocument",
    versionConst: "AUDIT_BUNDLE_SCHEMA_VERSION",
    title: (version) => `nexus audit bundle v${version}`,
    description:
      "Generated from AuditBundleDocument in cli/src/audit_contract.ts by cli/scripts/gen_audit_schema.mjs. Do not edit by hand. A document of an audit bundle: manifest.json (AuditManifest), or the detached signature envelope manifest.sig.json (AuditSignatureEnvelope).",
  });
}

/** The schema text for `AuditVerifyOutput` as src/audit_contract.ts declares it now, and its `AUDIT_VERIFY_RESULT_SCHEMA_VERSION`. */
export function generateAuditVerifyResultSchema() {
  return generateResultSchema({
    script: SCRIPT,
    source: SOURCE,
    rootType: "AuditVerifyOutput",
    versionConst: "AUDIT_VERIFY_RESULT_SCHEMA_VERSION",
    title: (version) => `nexus audit verify output v${version}`,
    description:
      "Generated from AuditVerifyOutput in cli/src/audit_contract.ts by cli/scripts/gen_audit_schema.mjs. Do not edit by hand. The one JSON document a verification of an audit bundle prints; `schema_version` is its first member. A result has `result`; an error document does not.",
  });
}

/** The version-decision rule for the bundle ledger (see resultLedgerProblem). Returns what is wrong, or undefined. */
export function auditBundleLedgerProblem(schemaText, ledger, version) {
  return resultLedgerProblem(schemaText, ledger, version, "AUDIT_BUNDLE_SCHEMA_VERSION");
}

/** The version-decision rule for the verify-result ledger (see resultLedgerProblem). Returns what is wrong, or undefined. */
export function auditVerifyResultLedgerProblem(schemaText, ledger, version) {
  return resultLedgerProblem(schemaText, ledger, version, "AUDIT_VERIFY_RESULT_SCHEMA_VERSION");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  // Each call exits 1 on a stale schema or ledger, so with --check the second runs only when the first is current.
  resultSchemaMain({ script: SCRIPT, generate: generateAuditBundleSchema, schemaFile: auditBundleSchemaFile, ledgerFile: AUDIT_BUNDLE_LEDGER_FILE, ledgerProblem: auditBundleLedgerProblem });
  resultSchemaMain({ script: SCRIPT, generate: generateAuditVerifyResultSchema, schemaFile: auditVerifyResultSchemaFile, ledgerFile: AUDIT_VERIFY_RESULT_LEDGER_FILE, ledgerProblem: auditVerifyResultLedgerProblem });
}
// Generates the JSON Schema (draft 2020-12) of a managed policy document (GV-1) from the type `ManagedPolicyFile` in
// src/core/managed_policy.ts, with the `SchemaBuilder` of gen_protocol_schema.mjs through result_schema.mjs (see
// docs/protocol/README.md): deterministic output, compared byte for byte. A policy file is TOML; the schema describes
// the same data as a JSON document (a table is an object), for an operator's editor or linter.
//
//   node scripts/gen_policy_schema.mjs           write docs/protocol/policy-v<N>.schema.json
//   node scripts/gen_policy_schema.mjs --check   exit 1 when the checked-in schema or the version ledger is stale
import path from "node:path";
import { fileURLToPath } from "node:url";
import { generateResultSchema, repo, resultLedgerProblem, resultSchemaMain } from "./result_schema.mjs";

const SCRIPT = "gen_policy_schema";

export const POLICY_LEDGER_FILE = path.join(repo, "docs", "protocol", "POLICY_VERSIONS.json");
export const policySchemaFile = (version) => path.join(repo, "docs", "protocol", `policy-v${version}.schema.json`);

/** The schema text for `ManagedPolicyFile` as src/core/managed_policy.ts declares it now, and its `POLICY_SCHEMA_VERSION`. */
export function generatePolicySchema() {
  return generateResultSchema({
    script: SCRIPT,
    source: "src/core/managed_policy.ts",
    rootType: "ManagedPolicyFile",
    versionConst: "POLICY_SCHEMA_VERSION",
    title: (version) => `nexus managed policy v${version}`,
    description:
      "Generated from ManagedPolicyFile in cli/src/core/managed_policy.ts by cli/scripts/gen_policy_schema.mjs. Do not edit by hand. The data of a managed policy file (policy.toml): each TOML table is an object, and `schema_version` is required. The schema describes shape only; Nexus's own validator is stricter (see docs/MANAGED_POLICY.md).",
  });
}

/** The version-decision rule for the policy ledger (see resultLedgerProblem). Returns what is wrong, or undefined. */
export function policyLedgerProblem(schemaText, ledger, version) {
  return resultLedgerProblem(schemaText, ledger, version, "POLICY_SCHEMA_VERSION");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  resultSchemaMain({ script: SCRIPT, generate: generatePolicySchema, schemaFile: policySchemaFile, ledgerFile: POLICY_LEDGER_FILE, ledgerProblem: policyLedgerProblem });
}
// Shared `--name value` / `--name=value` parsing for the standalone CLI scripts.
// A missing value falls back rather than consuming the next flag (or process.argv[0]).
import path from "node:path";

export function optionValue(argv, name, fallback) {
  const flag = `--${name}`;
  const inline = argv.find((value) => typeof value === "string" && value.startsWith(`${flag}=`));
  if (inline !== undefined) {
    const value = inline.slice(flag.length + 1);
    return value || fallback;
  }
  const at = argv.indexOf(flag);
  if (at < 0) return fallback;
  const value = argv[at + 1];
  return typeof value === "string" && value && !value.startsWith("--") ? value : fallback;
}

/** Resolve the lcov output against the CLI root, not the caller's cwd. */
export function resolveCoverageOut(argv, env, cli) {
  const configured = optionValue(argv, "out", env.NEXUS_COVERAGE_OUT || path.join("coverage", "lcov.info"));
  return path.resolve(cli, configured);
}
// A small JSON Schema validator for the subset scripts/gen_protocol_schema.mjs emits (draft 2020-12 keywords: type,
// const, enum, properties, required, additionalProperties, items, prefixItems, minItems, maxItems, anyOf, oneOf and a
// local $ref). It is a test helper, not a general validator: a keyword outside that subset throws, so a generator that
// starts emitting a new keyword cannot pass unvalidated.
import { isDeepStrictEqual } from "node:util";

export type Schema = Record<string, any>;

const ANNOTATIONS = new Set(["$schema", "$defs", "title", "description"]);
const KEYWORDS = new Set(["$ref", "type", "const", "enum", "properties", "required", "additionalProperties", "items", "prefixItems", "minItems", "maxItems", "anyOf", "oneOf"]);

function typeName(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

function resolve(root: Schema, ref: string): Schema {
  if (!ref.startsWith("#/")) throw new Error(`unsupported $ref: ${ref}`);
  let node: any = root;
  for (const part of ref.slice(2).split("/")) node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
  if (!node || typeof node !== "object") throw new Error(`unresolved $ref: ${ref}`);
  return node;
}

/** Every way `value` fails `schema`, as `path: reason` lines; empty when it is valid. `root` resolves `$ref`. */
export function validate(value: unknown, schema: Schema, root: Schema = schema, at = "$"): string[] {
  for (const keyword of Object.keys(schema)) {
    if (!KEYWORDS.has(keyword) && !ANNOTATIONS.has(keyword)) throw new Error(`unsupported schema keyword at ${at}: ${keyword}`);
  }
  const errors: string[] = [];
  if (schema.$ref) errors.push(...validate(value, resolve(root, schema.$ref), root, at));
  const actual = typeName(value);
  if (schema.type !== undefined && actual !== schema.type) errors.push(`${at}: expected ${schema.type}, got ${actual}`);
  if ("const" in schema && !isDeepStrictEqual(value, schema.const)) errors.push(`${at}: expected ${JSON.stringify(schema.const)}`);
  if (schema.enum && !schema.enum.some((allowed: unknown) => isDeepStrictEqual(value, allowed))) errors.push(`${at}: not one of ${JSON.stringify(schema.enum)}`);

  if (actual === "object") {
    const object = value as Record<string, unknown>;
    const properties: Record<string, Schema> = schema.properties ?? {};
    for (const name of schema.required ?? []) {
      if (!Object.hasOwn(object, name)) errors.push(`${at}: missing required ${name}`);
    }
    for (const [name, member] of Object.entries(object)) {
      if (Object.hasOwn(properties, name)) errors.push(...validate(member, properties[name], root, `${at}.${name}`));
      else if (schema.additionalProperties === false) errors.push(`${at}: unexpected property ${name}`);
      else if (typeof schema.additionalProperties === "object") errors.push(...validate(member, schema.additionalProperties, root, `${at}.${name}`));
    }
  }

  if (actual === "array") {
    const array = value as unknown[];
    const prefix: Schema[] = schema.prefixItems ?? [];
    if (schema.minItems !== undefined && array.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
    if (schema.maxItems !== undefined && array.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
    array.forEach((item, i) => {
      if (i < prefix.length) errors.push(...validate(item, prefix[i], root, `${at}[${i}]`));
      else if (schema.items) errors.push(...validate(item, schema.items, root, `${at}[${i}]`));
    });
  }

  for (const keyword of ["anyOf", "oneOf"] as const) {
    if (!schema[keyword]) continue;
    const results: string[][] = schema[keyword].map((option: Schema) => validate(value, option, root, at));
    const matches = results.filter((result) => result.length === 0).length;
    if (matches === 1 || (matches > 1 && keyword === "anyOf")) continue;
    if (matches > 1) {
      errors.push(`${at}: matches ${matches} oneOf alternatives`);
      continue;
    }
    // Explain with the alternative that came closest. For a message union that is the variant whose `type` matched;
    // when no variant's did, the type is unknown and there is nothing more to say.
    const candidates = results.filter((result) => !result.some((error) => error.startsWith(`${at}.type:`)));
    const closest = candidates.reduce<string[]>((best, result) => (best.length === 0 || result.length < best.length ? result : best), []);
    errors.push(`${at}: matches no ${keyword} alternative`, ...closest);
  }
  return errors;
}
/**
 * GV-2: the published schemas of the audit bundle (docs/protocol/audit-bundle-v1.schema.json: the manifest and the
 * signature envelope) and of the verification result (audit-verify-result-v1.schema.json), their version ledgers, and
 * the exit-code table. The documents themselves are validated where they are produced: every manifest and every result
 * in test/audit_bundle.test.ts goes through these schemas (helpers/audit_fixture.ts).
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { sha256 } from "../scripts/gen_protocol_schema.mjs";
import {
  AUDIT_BUNDLE_LEDGER_FILE,
  AUDIT_VERIFY_RESULT_LEDGER_FILE,
  auditBundleLedgerProblem,
  auditVerifyResultLedgerProblem,
  generateAuditBundleSchema,
  generateAuditVerifyResultSchema,
} from "../scripts/gen_audit_schema.mjs";
import {
  AUDIT_BUNDLE_SCHEMA_VERSION,
  AUDIT_CHAINED_LOG_KINDS,
  AUDIT_EXIT_CODES,
  AUDIT_FILE_ROLES,
  AUDIT_VERIFY_RESULT_SCHEMA_VERSION,
  auditExitCode,
  type AuditSignatureEnvelope,
  type AuditVerifyError,
} from "../src/audit_contract.js";
import { RUN_EXIT_CODES } from "../src/run_contract.js";
import { VERIFY_EXIT_CODES } from "../src/verify_contract.js";
import { AUDIT_BUNDLE_SCHEMA as bundleSchema, AUDIT_BUNDLE_SCHEMA_TEXT, AUDIT_VERIFY_SCHEMA as verifySchema, AUDIT_VERIFY_SCHEMA_TEXT } from "./helpers/audit_fixture.js";
import { validate } from "./helpers/json_schema.js";

const published = [
  { name: "audit-bundle", generate: generateAuditBundleSchema, checkedIn: AUDIT_BUNDLE_SCHEMA_TEXT, version: AUDIT_BUNDLE_SCHEMA_VERSION, constant: "AUDIT_BUNDLE_SCHEMA_VERSION", ledgerFile: AUDIT_BUNDLE_LEDGER_FILE, problem: auditBundleLedgerProblem },
  { name: "audit-verify-result", generate: generateAuditVerifyResultSchema, checkedIn: AUDIT_VERIFY_SCHEMA_TEXT, version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, constant: "AUDIT_VERIFY_RESULT_SCHEMA_VERSION", ledgerFile: AUDIT_VERIFY_RESULT_LEDGER_FILE, problem: auditVerifyResultLedgerProblem },
];

for (const { name, generate, checkedIn, version, constant, ledgerFile, problem } of published) {
  test(`the checked-in ${name} schema equals a fresh generation from src/audit_contract.ts`, () => {
    const generated = generate();
    assert.equal(generated.version, version);
    assert.equal(generated.text, checkedIn, `docs/protocol/${name} schema is out of date: run \`node cli/scripts/gen_audit_schema.mjs\`, then record the version decision in its ledger`);
  });

  test(`the newest ${name} ledger entry records the current schema and schema_version`, () => {
    const ledger = JSON.parse(fs.readFileSync(ledgerFile, "utf8"));
    assert.equal(problem(checkedIn, ledger, version), undefined);
    for (const entry of ledger) {
      assert.ok(Number.isInteger(entry.schema_version) && /^[0-9a-f]{64}$/.test(entry.schemaSha256) && typeof entry.note === "string" && entry.note.trim(), "each entry has schema_version, schemaSha256 and a note");
    }
    // The rule itself: a changed schema, or a version bump, without a new entry is a failure.
    assert.match(problem(`${checkedIn} `, ledger, version) ?? "", /add an entry/);
    assert.match(problem(checkedIn, ledger, version + 1) ?? "", new RegExp(`${constant} is`));
    assert.match(problem(checkedIn, [], version) ?? "", /no entries/);
    assert.equal(ledger[ledger.length - 1].schemaSha256, sha256(checkedIn));
  });
}

test("the bundle schema is the manifest or the signature envelope, with the contract's roles, kinds and required members", () => {
  assert.equal(bundleSchema.$schema, "https://json-schema.org/draft/2020-12/schema");
  assert.deepEqual(bundleSchema.$defs.AuditBundleDocument.anyOf, [{ $ref: "#/$defs/AuditManifest" }, { $ref: "#/$defs/AuditSignatureEnvelope" }]);
  const manifest = bundleSchema.$defs.AuditManifest;
  assert.deepEqual(manifest.required, ["bundle_id", "chained_logs", "created_at", "files", "files_head", "format", "nexus", "omitted", "redaction", "root_sha256", "schema_version", "subject"]);
  assert.deepEqual([manifest.properties.schema_version.const, manifest.properties.format.const], [AUDIT_BUNDLE_SCHEMA_VERSION, "nexus-audit-bundle/1"]);
  assert.deepEqual(bundleSchema.$defs.AuditFileEntry.required, ["bytes", "chain", "path", "role", "sha256"]);
  assert.deepEqual(bundleSchema.$defs.AuditFileEntry.properties.role.enum, [...AUDIT_FILE_ROLES].sort());
  assert.deepEqual(bundleSchema.$defs.AuditChainedLog.properties.kind.enum, [...AUDIT_CHAINED_LOG_KINDS].sort());
  assert.deepEqual(bundleSchema.$defs.AuditChainedLog.required, ["kind", "path", "records", "status"]);
  assert.deepEqual(bundleSchema.$defs.ChainLink.required, ["hash", "prev", "seq"]);

  const envelope: AuditSignatureEnvelope = { schema_version: 1, algorithm: "ed25519", signed_file: "manifest.json", manifest_sha256: "0".repeat(64), public_key_sha256: "1".repeat(64), signature: "c2ln" };
  assert.deepEqual(validate(envelope, bundleSchema, bundleSchema), []);
  assert.deepEqual(bundleSchema.$defs.AuditSignatureEnvelope.required, Object.keys(envelope).sort());
  assert.ok(validate({ ...envelope, algorithm: "rsa" }, bundleSchema, bundleSchema).length > 0);
  assert.ok(validate({ schema_version: 1, format: "nexus-audit-bundle/1" }, bundleSchema, bundleSchema).length > 0, "a manifest without its required members");
});

test("the audit JSON schema is an export result, verification result, or error document; required fields stay explicit", () => {
  assert.deepEqual(verifySchema.$defs.AuditVerifyOutput.anyOf, [{ $ref: "#/$defs/AuditExportResult" }, { $ref: "#/$defs/AuditVerifyError" }, { $ref: "#/$defs/AuditVerifyResult" }]);
  for (const name of ["AuditExportResult", "AuditVerifyResult", "AuditVerifyError"]) {
    const branch = verifySchema.$defs[name];
    assert.equal(branch.properties.schema_version.const, AUDIT_VERIFY_RESULT_SCHEMA_VERSION);
    assert.ok(branch.required.includes("schema_version") && branch.required.includes("exitCode"));
  }
  assert.deepEqual(verifySchema.$defs.AuditVerifyResult.required, ["bundle_id", "chained_logs", "exitCode", "expected_manifest_sha256", "files", "findings", "findings_total", "manifest_sha256", "notes", "public_key_sha256", "result", "schema_version", "signature"]);
  assert.ok(!("result" in verifySchema.$defs.AuditVerifyError.properties));
  assert.deepEqual(verifySchema.$defs.AuditVerifyResultName.enum, ["intact_signed", "intact_unsigned", "signature_unchecked", "tampered", "unsupported_version"]);
  assert.deepEqual(verifySchema.$defs.AuditFindingKind.enum, [
    "file_altered",
    "file_missing",
    "file_unexpected",
    "limit_exceeded",
    "log_chain_broken",
    "log_head_mismatch",
    "manifest_chain_broken",
    "manifest_malformed",
    "manifest_missing",
    "manifest_not_canonical",
    "manifest_root_mismatch",
    "manifest_sha256_mismatch",
    "signature_invalid",
    "signature_key_mismatch",
    "signature_missing",
    "unreadable_entry",
    "unsafe_entry",
    "unsupported_version",
  ]);
  assert.deepEqual(verifySchema.$defs.AuditSignatureStatus.enum, ["absent", "invalid", "missing", "unchecked", "valid"]);
  // Every result name is a row of the exit-code table.
  for (const name of verifySchema.$defs.AuditVerifyResultName.enum) assert.ok(AUDIT_EXIT_CODES.some((row) => row.name === name), name);

  const error: AuditVerifyError = { schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, error: "there is no bundle directory at that path", exitCode: 1 };
  assert.deepEqual(validate(error, verifySchema, verifySchema), []);
  assert.ok(validate({ ...error, schema_version: 2 }, verifySchema, verifySchema).length > 0);
  assert.ok(validate({ error: "x", exitCode: 1 }, verifySchema, verifySchema).length > 0, "a document without schema_version");
  assert.ok(validate({ schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, result: "intact_unsigned" }, verifySchema, verifySchema).length > 0, "a result without its required members");
});

test("the exit-code table: only an export or an intact bundle is 0, and the signing rows are already there", () => {
  assert.deepEqual(
    AUDIT_EXIT_CODES.map((row) => [row.code, row.name]),
    [
      [0, "exported"],
      [0, "intact_signed"],
      [0, "intact_unsigned"],
      [1, "tampered"],
      [1, "error"],
      [1, "option_parse"],
      [2, "signature_unchecked"],
      [2, "unsupported_version"],
      [2, "usage"],
      [2, "subject_not_found"],
      [130, "interrupted"],
    ],
  );
  assert.equal(new Set(AUDIT_EXIT_CODES.map((row) => row.name)).size, AUDIT_EXIT_CODES.length, "each name is one row");
  for (const row of AUDIT_EXIT_CODES) {
    assert.deepEqual(Object.keys(row), ["code", "name", "when"], "the row shape of RUN_EXIT_CODES and VERIFY_EXIT_CODES");
    assert.ok(row.when.trim().length > 0);
    assert.equal(auditExitCode(row.name), row.code);
  }
  assert.deepEqual(Object.keys(RUN_EXIT_CODES[0]), ["code", "name", "when"]);
  assert.deepEqual(Object.keys(VERIFY_EXIT_CODES[0]), ["code", "name", "when"]);
  // The rows shared with the other commands keep their codes.
  for (const name of ["option_parse", "usage", "interrupted"] as const) {
    assert.equal(auditExitCode(name), RUN_EXIT_CODES.find((row) => row.name === name)!.code);
    assert.equal(auditExitCode(name), VERIFY_EXIT_CODES.find((row) => row.name === name)!.code);
  }
});
