  SIDECAR_EVENT_DISPOSITION,
  TOOL_KINDS,
  VALIDATION_RECEIPT_SECTION,
  approvalDigest,
  approvalToPermissionRequest,
  assistantDeltaToUpdate,
  bindApprovalToToolCall,
  cancelledRequestError,
  fileDiffToUpdate,
  historyToReplay,
  initializeResult,
  loadSessionResult,
  newSessionResult,
  nexusReceipt,
  permissionReplyToCommand,
  postureFromState,
  promptResult,
  sessionUpdate,
  sidecarErrorToRpc,
  toolCallId,
  toolEndToUpdate,
  toolKind,
  toolStartToUpdate,
  turnToStop,
  unifiedDiffToBlocks,
  validationReceiptFromSections,
  verdictChunk,
  verificationFromTurn,
  verificationUpdate,
  type ApprovalCommand,
} from "../src/acp/mapping.js";
import * as acpTypes from "../src/acp/types.js";
