  ACP_ALLOW_ONCE_OPTION_ID,
  ACP_ERROR,
  ACP_MAX_DIFF_BLOCKS,
  ACP_MAX_ERROR_MESSAGE_CHARS,
  ACP_MAX_TOOL_TEXT_CHARS,
  ACP_META_PREFIX,
  ACP_EXTENSION_METHOD_PREFIX,
  ACP_PERMISSION_OPTIONS,
  ACP_REJECT_ONCE_OPTION_ID,
} from "../src/acp/types.js";
import {
  AGENT_EXAMPLES,
  APPROVALS,
  APPROVAL_ARGS,
